"""Fresh31 entries, previous duel first bout, current cargo/queue restore and native RTS win."""
import argparse,asyncio,datetime,json
from playwright.async_api import async_playwright
from test_expedition_browser import ROOT,FIELDS,snap,Pilot,begin,complete,load,watch
import test_duel_browser as duel
async def main(args):
 out=ROOT/args.out;out.parent.mkdir(parents=True,exist_ok=True);errors=[];bad=[];failed=[];report={'testedAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'url':args.url,'entryPages':[]};pilot=await Pilot().start();oldpilot=await duel.Pilot().start()
 def save():report.update(consoleErrors=errors,badResponses=bad,requestFailures=failed);out.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 async with async_playwright() as pw:
  b=await pw.chromium.launch()
  try:
   ctx=await b.new_context(viewport={'width':1360,'height':1100});p=await ctx.new_page();watch(p,errors,bad,failed);base=args.url.rstrip('/')+'/'
   await p.goto(base);await p.locator('.lab-card').last.wait_for();await p.wait_for_load_state('networkidle');data=await p.evaluate('async()=>await(await fetch("./data/games.json")).json()');assert len(data['games'])==72 and len(data['groups'])==10 and len(data['experiments'])==31 and sum(e['levels'] for e in data['experiments'])==374 and data['version']=='2026.10.16.31';assert await p.locator('.lab-card .primary-link').count()==31;report['atlas']={'entries':72,'groups':10,'originals':31,'levels':374,'version':data['version']};save()
   for e in data['experiments']:
    r=await p.goto(base+e['url'].removeprefix('./'));await p.wait_for_load_state('networkidle');assert r.status==200 and await p.locator('h1').count()==1 and await p.locator('main').count()>=1 and await p.locator('script[type=module]').count()>=1,e['id'];report['entryPages'].append({'id':e['id'],'status':r.status,'title':await p.title()});save()
   await duel.load(p,base+'games/duel/');d=await duel.Driver(p).start();await duel.begin(p,d);old,_,_=await duel.complete(p,oldpilot,d);assert old['state']=='won' and old['player']['hp']>0 and old['enemy']['hp']==0;await d.release();report['previousGame']={'id':'duel','state':old['state'],'hp':old['player']['hp'],'stats':old['stats'],'actualLog':old['log']};save()
   await load(p,base+'games/expedition/');await begin(p);partial,_,_=await complete(p,pilot,stop=lambda s:any(u['carry']>0 for u in s['units']) and bool(s['queue']));assert partial['state']=='playing' and partial['queue'];await p.keyboard.press('p');before=await snap(p);await load(p,base+'games/expedition/',True);after=await snap(p);assert after['state']=='paused' and after['ui']['pending'] is None and after['accumulator']==0 and all(before[k]==after[k] for k in FIELDS);await p.wait_for_timeout(500);waited=await snap(p);assert all(waited[k]==after[k] for k in FIELDS);await p.locator('#resume').click();end,_,_=await complete(p,pilot);assert end['state']=='won' and end['home']['hp']>0 and end['stats']['delivered']>=12 and end['stats']['produced']>=2;report['restoreAndWin']={'state':end['state'],'stock':end['stock'],'homeHP':end['home']['hp'],'score':end['score'],'exactFields':FIELDS,'restoredUnits':after['units'],'restoredQueue':after['queue'],'stats':end['stats'],'actualLog':end['log']};save();await ctx.close()
   ctx=await b.new_context(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);p=await ctx.new_page();watch(p,errors,bad,failed);await load(p,base+'games/expedition/');await begin(p,True);end,_,_=await complete(p,pilot,True);assert end['state']=='won' and end['home']['hp']>0;report['nativeTouch']={'state':end['state'],'homeHP':end['home']['hp'],'stock':end['stock'],'score':end['score'],'stats':end['stats'],'actualLog':end['log'],'method':'Native unit/group/mode/map/cost-preview/confirmation taps with actual scrolling; original resources/HP and1x.'};await ctx.close();assert not errors and not bad and not failed,(errors,bad,failed);report['passed']=True;save();print(json.dumps({'passed':True,'entryPages':len(report['entryPages']),'previousHP':report['previousGame']['hp'],'restoreStock':report['restoreAndWin']['stock'],'nativeStock':report['nativeTouch']['stock']}))
  except Exception as e:report['error']=type(e).__name__+': '+str(e)[:1800];raise
  finally:save();await b.close();await pilot.close();await oldpilot.close()
if __name__=='__main__':
 a=argparse.ArgumentParser();a.add_argument('--url',default='https://yydshly.github.io/classic-games-atlas/');a.add_argument('--out',default='.local/expedition-final-smoke.json');asyncio.run(main(a.parse_args()))
